/* cegueira à mudança: breve interrupção entre cenas */
.flicker-scene.running:after{
  content:"";
  position:absolute;
  inset:0;
  z-index:8;
  background:#fffdf8;
  pointer-events:none;
  animation:flicker-blank .52s steps(1,end) infinite;
}
@keyframes flicker-blank{
  0%,70%,100%{opacity:0}
  71%,88%{opacity:1}
}
