] as const;
const attentionBlue=attentionEvents.filter(v=>v==="blue").length;

export function AttentionTest(){
  const [phase,setPhase]=useState<"ready"|"run"|"count"|"noticed"|"result">("ready");
  const [tick,setTick]=useState(-1);
